import { Controller, Get, HttpCode, Patch, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const RESET_UNITS = ['DAY', 'MONTH', 'YEAR_PROJECT', 'YEAR_WORKPLACE'];
const TARGET_TYPES = ['DOCUMENT', 'APPROVAL', 'CERTIFICATE'];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const MAX_DIGITS = 2147483647;

function invalid(): ApiError {
  return new ApiError(422, 'NUMBERING_RULE_INVALID', '채번 규칙의 필수값 또는 형식이 올바르지 않습니다.');
}

function parseDigits(v: unknown): number | null {
  let n: number | null = null;
  if (typeof v === 'number' && Number.isInteger(v)) {
    n = v;
  } else if (typeof v === 'string' && /^\d+$/.test(v.trim())) {
    n = Number(v.trim());
  }
  if (n === null || n < 1 || n > MAX_DIGITS) {
    return null;
  }
  return n;
}

function parseWholeNumber(v: unknown, fallback: number): number {
  if (v === undefined || v === null || v === '') {
    return fallback;
  }
  if (typeof v === 'string' && /^\d+$/.test(v)) {
    return Number(v);
  }
  throw new ApiError(400, 'VALIDATION_FAILED', '요청 형식이 올바르지 않습니다.');
}

@Controller('api/v1')
export class FnSfr01602Controller {
  @Get('/numbering-rules')
  async listNumberingRules(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const query = checks.queryOf(req.query);
    const rawType = query['targetType'];
    let targetType: string | null = null;
    if (rawType !== undefined && rawType !== null && rawType !== '') {
      if (typeof rawType !== 'string' || !TARGET_TYPES.includes(rawType)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '대상 유형이 올바르지 않습니다.');
      }
      targetType = rawType;
    }
    const page = parseWholeNumber(query['page'], 0);
    const size = Math.min(parseWholeNumber(query['size'], DEFAULT_SIZE), MAX_SIZE);
    if (size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '요청 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const where = `WHERE (CAST(:targetType AS varchar) IS NULL OR target_type = CAST(:targetType AS varchar))`;
      const items = await db.query(
        `SELECT numbering_rule_id AS "numberingRuleId",
                target_type AS "targetType",
                reset_unit AS "resetUnit",
                prefix AS "prefix",
                digits AS "digits"
           FROM numbering_rule
          ${where}
          ORDER BY numbering_rule_id DESC
          LIMIT :size OFFSET :offset`,
        { targetType, size, offset: page * size },
      );
      const counts = await db.query(
        `SELECT COUNT(*) AS "total" FROM numbering_rule ${where}`,
        { targetType },
      );
      return { items, page, size, total: Number(counts[0]['total']) };
    });
  }

  @Post('/numbering-rules')
  @HttpCode(200)
  async createNumberingRule(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const data = checks.inputOf(req.body);
    const resetUnit = data['resetUnit'];
    if (typeof resetUnit !== 'string' || !RESET_UNITS.includes(resetUnit)) {
      throw invalid();
    }
    const digits = parseDigits(data['digits']);
    if (digits === null) {
      throw invalid();
    }
    let prefix: string | null = null;
    const rawPrefix = data['prefix'];
    if (rawPrefix !== undefined && rawPrefix !== null && rawPrefix !== '') {
      if (typeof rawPrefix !== 'string' || rawPrefix.length > 20) {
        throw invalid();
      }
      prefix = rawPrefix;
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `INSERT INTO numbering_rule (target_type, reset_unit, prefix, digits, created_at, updated_at)
         VALUES ('CERTIFICATE', :resetUnit, :prefix, CAST(:digits AS integer), now(), now())
         RETURNING numbering_rule_id AS "numberingRuleId"`,
        { resetUnit, prefix, digits },
      );
      return rows[0];
    });
  }

  @Patch('/numbering-rules/:numberingRuleId')
  async updateNumberingRule(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const idText = req.params['numberingRuleId'];
    if (!/^\d+$/.test(idText)) {
      throw new ApiError(404, 'NUMBERING_RULE_NOT_FOUND', '채번 규칙을 찾을 수 없습니다.');
    }
    const data = checks.inputOf(req.body);
    let resetUnit: string | null = null;
    if (data['resetUnit'] !== undefined && data['resetUnit'] !== null) {
      const v = data['resetUnit'];
      if (typeof v !== 'string' || !RESET_UNITS.includes(v)) {
        throw invalid();
      }
      resetUnit = v;
    }
    let digits: number | null = null;
    if (data['digits'] !== undefined && data['digits'] !== null) {
      digits = parseDigits(data['digits']);
      if (digits === null) {
        throw invalid();
      }
    }
    const hasPrefix = data['prefix'] !== undefined;
    let prefix: string | null = null;
    if (hasPrefix && data['prefix'] !== null && data['prefix'] !== '') {
      const v = data['prefix'];
      if (typeof v !== 'string' || v.length > 20) {
        throw invalid();
      }
      prefix = v;
    }
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT numbering_rule_id FROM numbering_rule WHERE numbering_rule_id = CAST(:id AS bigint)`,
        { id: idText },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'NUMBERING_RULE_NOT_FOUND', '채번 규칙을 찾을 수 없습니다.');
      }
      // 변경은 이후 발급 건부터 적용된다. 이미 부여된 번호는 건드리지 않는다.
      const rows = await db.query(
        `UPDATE numbering_rule
            SET reset_unit = COALESCE(CAST(:resetUnit AS varchar), reset_unit),
                digits = COALESCE(CAST(:digits AS integer), digits),
                prefix = CASE WHEN CAST(:hasPrefix AS boolean) THEN CAST(:prefix AS varchar) ELSE prefix END,
                updated_at = now()
          WHERE numbering_rule_id = CAST(:id AS bigint)
          RETURNING numbering_rule_id AS "numberingRuleId"`,
        { resetUnit, digits, hasPrefix, prefix, id: idText },
      );
      return rows[0];
    });
  }
}

