import { useState } from 'react';
import { Badge, Band, DataTable, Drawer, Field, Filters, Form, NumberInput, Pager, Select, TextInput, Tiles, call, useData } from '../kit';
import type { Page, PageProps, Row } from '../kit';

const SIZE = 20;

const TARGET_OPTIONS: [string, string][] = [
  ['DOCUMENT', '문서'],
  ['APPROVAL', '승인'],
  ['CERTIFICATE', '증명서'],
];

const RESET_OPTIONS: [string, string][] = [
  ['DAY', '일'],
  ['MONTH', '월'],
  ['YEAR_PROJECT', '연도(프로젝트)'],
  ['YEAR_WORKPLACE', '연도(사업장)'],
];

function labelOf(options: [string, string][], value: unknown): string {
  const found = options.find((o) => o[0] === value);
  return found ? found[1] : String(value ?? '');
}

function RuleForm({ role, rule, onDone, notify }: { role: string; rule?: Row; onDone: () => void; notify: (text: string) => void }) {
  const [resetUnit, setResetUnit] = useState<string>(rule ? String(rule.resetUnit ?? '') : '');
  const [prefix, setPrefix] = useState<string>(rule ? String(rule.prefix ?? '') : '');
  const [digits, setDigits] = useState<number | string>(rule ? Number(rule.digits) : '');

  async function submit() {
    if (!resetUnit) {
      throw new Error('채번 단위를 선택하세요.');
    }
    if (digits === '' || Number(digits) < 1 || !Number.isInteger(Number(digits))) {
      throw new Error('자릿수는 1 이상의 정수로 입력하세요.');
    }
    const body: Row = { resetUnit, prefix, digits: Number(digits) };
    if (rule) {
      await call('PATCH', '/numbering-rules/' + String(rule.numberingRuleId), role, body);
      notify('채번 규칙을 수정했습니다.');
    } else {
      await call('POST', '/numbering-rules', role, body);
      notify('채번 규칙을 등록했습니다.');
    }
    onDone();
  }

  return (
    <Form
      onSubmit={submit}
      submit={rule ? '수정' : '등록'}
      note={rule ? '변경은 이후 발급 건부터 적용됩니다.' : undefined}
    >
      <Field label="채번 단위" required>
        <Select value={resetUnit} onChange={setResetUnit} options={RESET_OPTIONS} />
      </Field>
      <Field label="접두어">
        <TextInput value={prefix} onChange={setPrefix} />
      </Field>
      <Field label="자릿수" required>
        <NumberInput value={digits} onChange={setDigits} />
      </Field>
    </Form>
  );
}

export default function FnSfr01602Page({ role, notify }: PageProps) {
  const [page, setPage] = useState(0);
  const [targetType, setTargetType] = useState('');
  const [applied, setApplied] = useState('');
  const [creating, setCreating] = useState(false);
  const [editing, setEditing] = useState<Row | null>(null);

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/numbering-rules', role, undefined, { targetType: applied, page, size: SIZE }),
    [role, applied, page],
  );

  function done() {
    setCreating(false);
    setEditing(null);
    reload();
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>규칙 현황</h2>
        <Tiles items={[['채번 규칙 수', data ? data.total : 0]]} />
      </section>
      <section className="box span-12">
        <h2>채번 규칙</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            setApplied(targetType);
          }}
          onReset={() => {
            setTargetType('');
            setApplied('');
            setPage(0);
          }}
        >
          <Field label="대상 유형">
            <Select value={targetType} onChange={setTargetType} options={TARGET_OPTIONS} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={data ? data.total : 0}>
          <button type="button" onClick={() => setCreating(true)}>증명서 채번 규칙 등록</button>
        </Band>
        {error ? <p>{error}</p> : null}
        <DataTable
          columns={[
            { key: 'numberingRuleId', label: '채번 규칙 ID' },
            { key: 'targetType', label: '대상 유형', render: (r) => <Badge value={labelOf(TARGET_OPTIONS, r.targetType)} /> },
            { key: 'resetUnit', label: '채번 단위', render: (r) => <span>{labelOf(RESET_OPTIONS, r.resetUnit)}</span> },
            { key: 'prefix', label: '접두어' },
            { key: 'digits', label: '자릿수' },
            {
              key: 'actions',
              label: '처리',
              render: (r) => (
                <button type="button" onClick={() => setEditing(r)}>수정</button>
              ),
            },
          ]}
          rows={data ? data.items : []}
          empty="등록된 채번 규칙이 없습니다."
        />
        <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
      </section>
      {creating ? (
        <Drawer title="증명서 채번 규칙 등록" onClose={() => setCreating(false)}>
          <RuleForm role={role} onDone={done} notify={notify} />
        </Drawer>
      ) : null}
      {editing ? (
        <Drawer title="채번 규칙 수정" onClose={() => setEditing(null)}>
          <RuleForm role={role} rule={editing} onDone={done} notify={notify} />
        </Drawer>
      ) : null}
    </div>
  );
}
